namespace CSharpPracticum.Tasks.Level2;
internal class InsufficientFundsException(string message):Exception(message){}internal class BankAccount{private decimal balance;public void Deposit(decimal amount){if(amount<=0)throw new ArgumentOutOfRangeException(nameof(amount));balance+=amount;}public void Withdraw(decimal amount){if(amount<=0)throw new ArgumentOutOfRangeException(nameof(amount));if(amount>balance)throw new InsufficientFundsException("Недостаточно средств.");balance-=amount;}public decimal Balance=>balance;}
internal class Task30_BankAccount:ITask{public string Title=>"Задание 30: BankAccount + собственное Exception";public string Description=>"Реализовать счёт с пополнением и снятием средств.";public string[] Requirements=>new[]{"Приватный баланс, Deposit и Withdraw.","InsufficientFundsException наследуется от Exception.","Показать успешное снятие и попытку превысить баланс через try/catch."};public void Run(){BankAccount a=new();a.Deposit(100);a.Withdraw(30);Console.WriteLine($"Остаток: {a.Balance}");try{a.Withdraw(100);}catch(InsufficientFundsException e){Console.WriteLine(e.Message);}}}
